"""Stateful streaming dedupe fixture."""

from __future__ import annotations

from copy import deepcopy


class WatermarkDeduper:
    """Deduplicate events by event_id with watermark and TTL semantics."""

    def __init__(self, *, allowed_lateness: int = 0, ttl: int = 100) -> None:
        if allowed_lateness < 0:
            raise ValueError(f"allowed_lateness must be >= 0, got {allowed_lateness}")
        if ttl < 1:
            raise ValueError(f"ttl must be >= 1, got {ttl}")

        self.allowed_lateness = allowed_lateness
        self.ttl = ttl
        self._watermark = float('-inf')
        self._seen: dict[str, int] = {}  # event_id -> last event_time

    def process(self, events: list[dict[str, object]]) -> list[dict[str, object]]:
        # Validate all events first
        for event in events:
            if "event_id" not in event or "event_time" not in event:
                raise ValueError("Event must contain 'event_id' and 'event_time'")
            if not isinstance(event["event_id"], str):
                raise ValueError(f"event_id must be a string, got {type(event['event_id'])}")
            if not isinstance(event["event_time"], int):
                raise ValueError(f"event_time must be an integer, got {type(event['event_time'])}")

        emitted: list[dict[str, object]] = []

        for event in events:
            event_id = event["event_id"]
            event_time = event["event_time"]

            # Check if event is late (event_time <= watermark)
            if event_time <= self._watermark:
                # Late event - drop without changing state
                continue

            # Check if we've already seen this event_id
            if event_id in self._seen:
                # Duplicate - drop without changing state
                continue

            # Non-late, non-duplicate event - emit and update state
            self._seen[event_id] = event_time
            emitted.append(deepcopy(event))

            # Advance watermark
            new_watermark = max(self._watermark, event_time - self.allowed_lateness)
            if new_watermark > self._watermark:
                self._watermark = new_watermark
                # Evict old event IDs based on TTL
                self._evict_expired()

        return emitted

    def _evict_expired(self) -> None:
        """Remove event IDs last seen at or before watermark - ttl."""
        threshold = self._watermark - self.ttl
        keys_to_remove = [
            event_id for event_id, last_time in self._seen.items()
            if last_time <= threshold
        ]
        for event_id in keys_to_remove:
            del self._seen[event_id]

    def snapshot(self) -> dict[str, object]:
        return {
            "allowed_lateness": self.allowed_lateness,
            "ttl": self.ttl,
            "watermark": self._watermark,
            "seen": deepcopy(self._seen),
        }

    def restore(self, snapshot: dict[str, object]) -> None:
        if not isinstance(snapshot.get("allowed_lateness"), int):
            raise ValueError("Invalid snapshot: allowed_lateness must be an integer")
        if not isinstance(snapshot.get("ttl"), int):
            raise ValueError("Invalid snapshot: ttl must be an integer")

        allowed_lateness = int(snapshot["allowed_lateness"])
        ttl = int(snapshot["ttl"])

        if allowed_lateness < 0:
            raise ValueError(f"allowed_lateness must be >= 0, got {allowed_lateness}")
        if ttl < 1:
            raise ValueError(f"ttl must be >= 1, got {ttl}")

        self.allowed_lateness = allowed_lateness
        self.ttl = ttl
        self._watermark = float(snapshot.get("watermark", float('-inf')))
        self._seen = deepcopy(dict(snapshot.get("seen", {})))

    def state_size(self) -> int:
        return len(self._seen)
